  3	struct ThreadCardProjectionState: Sendable {
  4	    private struct HostProjection: Sendable {
  5	        var sourceHostID: String?
  6	        var cards: [DockThreadCardDTO] = []
  7	        var freshness: StreamReconcilerFreshnessState = .connecting
  8	        var revision = 0
  9	        var complete: Bool?
 10	        var totalRows: Int?
 11	        var window: ProjectionWindow?
 12	    }
 13	
 14	    private var statesByHostID: [String: HostProjection] = [:]
 15	
 16	    mutating func reset(hosts: [DockHostConfiguration]) {
 17	        statesByHostID = Dictionary(
 18	            uniqueKeysWithValues: hosts.map { ($0.id, HostProjection()) }
 19	        )
 20	    }
 21	
 22	    mutating func ensureHosts(_ hosts: [DockHostConfiguration]) {
 23	        let validHostIDs = Set(hosts.map(\.id))
 24	        statesByHostID = statesByHostID.filter { validHostIDs.contains($0.key) }
 25	        for host in hosts where statesByHostID[host.id] == nil {
 26	            statesByHostID[host.id] = HostProjection()
 27	        }
 28	    }
 29	
 30	    mutating func apply(
 31	        _ snapshot: StreamReconcilerSnapshot<DockThreadCardDTO>,
 32	        host: DockHostConfiguration
 33	    ) {
 34	        var state = statesByHostID[host.id] ?? HostProjection()
 35	        guard snapshot.revision >= state.revision else {
 36	            return
 37	        }
 38	        state.sourceHostID = snapshot.viewKey.sourceHostID ?? state.sourceHostID
 39	        state.cards = snapshot.rows
 40	        state.freshness = snapshot.freshness
 41	        state.revision = snapshot.revision
 42	        state.complete = snapshot.complete ?? state.complete
 43	        state.totalRows = snapshot.totalRows ?? state.totalRows
 44	        state.window = snapshot.window ?? state.window
 45	        statesByHostID[host.id] = state
 46	    }
 47	
 48	    func rowCount(for host: DockHostConfiguration) -> Int {
 49	        statesByHostID[host.id]?.cards.count ?? 0
 50	    }
 51	
 52	    func renderInput(hosts: [DockHostConfiguration]) -> DockRenderInput {
 53	        let hostStates = hosts.map { host in
 54	            DockHostStateViewModel(
 55	                host: DockHostViewModel(host: host),
 56	                status: hostStatus(for: host)
 57	            )
 58	        }
 59	        let statuses = Dictionary(
 60	            uniqueKeysWithValues: hostStates.map { ($0.host.id, $0.status) }
 61	        )
 62	        return DockRenderInput(
 63	            hosts: hosts,
 64	            hostStates: hostStates,
 65	            hostIdentityResolver: DockHostIdentityResolver(
 66	                hosts: hosts,
 67	                observations: identityObservations(hosts: hosts),
 68	                hostStatuses: statuses
 69	            ),
 70	            cardsByHostID: Dictionary(
 71	                uniqueKeysWithValues: hosts.map { host in
 72	                    (host.id, statesByHostID[host.id]?.cards ?? [])
 73	                }
 74	            ),
 75	            isPartial: hosts.contains(where: needsProgressContext)
 76	        )
 77	    }
 78	
 79	    func hostIdentityResolver(hosts: [DockHostConfiguration]) -> DockHostIdentityResolver {
 80	        DockHostIdentityResolver(
 81	            hosts: hosts,
 82	            observations: identityObservations(hosts: hosts),
 83	            hostStatuses: Dictionary(
 84	                uniqueKeysWithValues: hosts.map { ($0.id, hostStatus(for: $0)) }
 85	            )
 86	        )
 87	    }
 88	
 89	    private func hostStatus(for host: DockHostConfiguration) -> DockHostLoadStatus {
 90	        guard let state = statesByHostID[host.id] else {
 91	            return .checking
 92	        }
 93	        let rowCount = state.cards.count
 94	        let loadedWindow = hostWindow(
 95	            rowCount: rowCount,
 96	            complete: state.complete,
 97	            totalRows: state.totalRows,
 98	            window: state.window
 99	        )
100	        switch state.freshness {
101	        case .connecting, .subscribing:
102	            return rowCount > 0 ? .degraded(rowCount: rowCount, message: "Reconnecting") : .checking
103	        case .catchingUp(let reason):
104	            let message = reason == .manualRefresh ? "Refreshing" : "Reconnecting"
105	            return rowCount > 0 ? .degraded(rowCount: rowCount, message: message) : .checking
106	        case .live:
107	            if rowCount == 0, loadedWindow == nil {
108	                return .empty
109	            }
110	            return .loaded(rowCount: rowCount, window: loadedWindow)
111	        case .stale(let message):
112	            return .degraded(rowCount: rowCount, message: message)
113	        case .offline(let message):
114	            return rowCount > 0 ? .degraded(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
115	        case .failed(let message):
116	            return rowCount > 0 ? .degraded(rowCount: rowCount, message: message) : .error(message)
117	        case .closed:
118	            return rowCount == 0 ? .empty : .loaded(rowCount: rowCount, window: loadedWindow)
119	        }
120	    }
121	
122	    private func identityObservations(hosts: [DockHostConfiguration]) -> [DockHostIdentityObservation] {
123	        hosts.flatMap { host in
124	            guard let state = statesByHostID[host.id] else {
125	                return [DockHostIdentityObservation]()
126	            }
127	            var observations = [DockHostIdentityObservation(
128	                configuredHostID: host.id,
129	                streamHostID: state.sourceHostID
130	            )]
131	            observations.append(contentsOf: state.cards.map {
132	                DockHostIdentityObservation(configuredHostID: host.id, card: $0)
133	            })
134	            return observations
135	        }
136	    }
137	
138	    private func needsProgressContext(_ host: DockHostConfiguration) -> Bool {
139	        let status = hostStatus(for: host)
140	        if case .checking = status {
141	            return true
142	        }
143	        return status.isDegraded
144	    }
145	
146	    private func hostWindow(
147	        rowCount: Int,
148	        complete: Bool?,
149	        totalRows: Int?,
150	        window: ProjectionWindow?
151	    ) -> DockHostWindow? {
152	        guard complete != true else {
153	            return nil
154	        }
155	        let visibleRows = rowCount
156	        let knownTotal = max(totalRows ?? window?.rowCount ?? visibleRows, visibleRows)
157	        guard knownTotal > visibleRows else {
158	            return nil
159	        }
160	        return DockHostWindow(visibleRows: visibleRows, totalRows: knownTotal)
161	    }
162	}

