363	    private func applySnapshot(
364	        _ envelope: ProjectionEnvelope<Row>,
365	        recoveryReason: StreamReconcilerRecoveryReason?
366	    ) throws {
367	        latestEnvelopeKind = envelope.kind
368	        guard validateViewKey(envelope), envelope.kind == .snapshot else {
369	            throw ProjectionReducerError.streamContract("Projection subscribe/resync must return a snapshot for the reconciler view key.")
370	        }
371	        try reducer.apply(envelope, policy: policy)
372	        resolvedSourceHostID = envelope.sourceHostID
373	        resolvedViewParamsKey = envelope.viewParamsKey
374	        updateProjectionMetadata(from: envelope)
375	        activeTurnID = envelope.activeTurnID
376	        if isCatchupComplete(envelope) {
377	            activeCatchupReason = nil
378	            freshness = freshnessState(after: envelope)
379	        } else {
380	            let reason = recoveryReason ?? .manualRefresh
381	            activeCatchupReason = reason
382	            freshness = .catchingUp(reason)
383	        }
384	        lastError = lastError(after: freshness)
385	        scheduleHeartbeatIfNeeded()
386	        publish()
387	    }
