393	            updateProjectionMetadata(from: envelope)
394	            activeTurnID = envelope.activeTurnID
395	            if isCatchupComplete(envelope) {
396	                activeCatchupReason = nil
397	                freshness = freshnessState(after: envelope)
398	                lastError = lastError(after: freshness)
399	                scheduleHeartbeatIfNeeded()
400	                publish()
401	                await drainBufferedEnvelopes()
402	            } else if let activeCatchupReason {
403	                freshness = .catchingUp(activeCatchupReason)
