411	    private func drainBufferedEnvelopes() async {
412	        while !bufferedEnvelopes.isEmpty {
413	            if activeCatchupReason != nil,
414	               bufferedEnvelopes.first?.kind != .page {
415	                return
416	            }
417	            let next = bufferedEnvelopes.removeFirst()
418	            await applyIncoming(next)
419	            if isResyncing || pendingRecoveryReason != nil {
420	                return
421	            }
422	        }
423	    }
