426	        latestEnvelopeKind = envelope.kind
427	        if bufferedEnvelopes.count >= maxBufferedEnvelopeCount {
428	            bufferedEnvelopes.removeAll()
429	            if isResyncing {
430	                pendingRecoveryReason = .bufferOverflow
431	            } else {
432	                await requestResync(reason: .bufferOverflow)
433	            }
434	            return
435	        }
436	        bufferedEnvelopes.append(envelope)
437	        publish()
