440	    private func handleReducerError(_ error: Error) async {
441	        switch error {
442	        case ProjectionReducerError.sequenceGap:
443	            await requestResync(reason: .sequenceGap)
444	        case ProjectionReducerError.resyncRequired:
445	            await requestResync(reason: .relayResyncRequired)
446	        case ProjectionReducerError.epochMismatch,
447	             ProjectionReducerError.schemaMismatch,
448	             ProjectionReducerError.streamContract:
449	            await requestResync(reason: .streamContract)
450	        default:
451	            await markFailed(error)
452	        }
453	    }
