455	    private func validateViewKey(_ envelope: ProjectionEnvelope<Row>) -> Bool {
456	        guard envelope.view == viewKey.view,
457	              envelope.scope == viewKey.scope,
458	              !envelope.sourceHostID.isEmpty,
459	              let envelopeViewParamsKey = envelope.viewParamsKey,
460	              !envelopeViewParamsKey.isEmpty else {
461	            return false
462	        }
463	        let expectedSourceHostID = resolvedSourceHostID ?? viewKey.sourceHostID
464	        let expectedViewParamsKey = resolvedViewParamsKey ?? viewKey.viewParamsKey
465	        return (expectedSourceHostID == nil || envelope.sourceHostID == expectedSourceHostID)
466	            && (expectedViewParamsKey == nil || envelopeViewParamsKey == expectedViewParamsKey)
467	    }
