402	    private func groupPrecedes(_ lhs: DockProjectionGroupViewModel, _ rhs: DockProjectionGroupViewModel) -> Bool {
403	        if let lhsOrderKey = lhs.displayOrderKey,
404	           let rhsOrderKey = rhs.displayOrderKey,
405	           lhsOrderKey != rhsOrderKey {
406	            return lhsOrderKey < rhsOrderKey
407	        }
408	        if lhs.displayOrderKey != nil {
409	            return true
410	        }
411	        if rhs.displayOrderKey != nil {
412	            return false
413	        }
414	
415	        let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
416	        if titleOrder != .orderedSame {
417	            return titleOrder == .orderedAscending
418	        }
419	        return lhs.id < rhs.id
420	    }
421	
422	    private func rowPrecedesByRelayOrder(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
423	        // Dock rows are relay projection rows. Swift may filter and group them,
424	        // but visual order must remain relay displayOrderKey + projectionID.
425	        if lhs.displayOrderKey == rhs.displayOrderKey {
426	            return stableRowID(lhs) < stableRowID(rhs)
427	        }
428	        return lhs.displayOrderKey < rhs.displayOrderKey
429	    }
430	
431	    private func pinnedRowPrecedes(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
432	        if let lhsOrder = lhs.pinnedOrder,
433	           let rhsOrder = rhs.pinnedOrder,
434	           lhsOrder != rhsOrder {
435	            return lhsOrder < rhsOrder
436	        }
437	        if lhs.pinnedOrder != nil {
438	            return true
439	        }
440	        if rhs.pinnedOrder != nil {
441	            return false
442	        }
443	
444	        let lhsPinnedAt = lhs.pinnedAt ?? Date.distantPast
445	        let rhsPinnedAt = rhs.pinnedAt ?? Date.distantPast
446	        if lhsPinnedAt != rhsPinnedAt {
447	            return lhsPinnedAt < rhsPinnedAt
448	        }
449	
450	        return stableRowID(lhs) < stableRowID(rhs)
451	    }
452	
453	    private func stableRowID(_ row: DockRowViewModel) -> String {
454	        row.id
455	    }
