455	        index: Int,
456	        includeDockSweep: Bool = false,
457	        includeDetailSweep: Bool = false,
458	        includeDetailRequestElements: Bool = true,
459	        configuredHostIDs: [String] = []
460	    ) -> DisplayedUISample {
461	        let sampledAt = codexDockISO8601Now()
462	        let dockRoot = displayedUIElement(id: AutomationID.Dock.root.rawValue)
463	        let rootValue = dockRoot.exists ? dockRoot.displayedUIStringValue : "not-visible"
