482	        let globalConnectivity = detail == nil ? globalConnectivitySnapshot() : nil
483	        // Dock host summaries are Dock-screen evidence only. Querying them from
484	        // Thread Detail forces a broad accessibility scan and can drop the UI
485	        // test connection before the real detail sample is written.
486	        let hostSummaries = detail == nil && configuredHostIDs.isEmpty ? hostSummarySnapshots() : []
487	        return DisplayedUISample(
488	            sampleIndex: index,
489	            sampledAt: sampledAt,
490	            finishedAt: codexDockISO8601Now(),
491	            dockRootValue: rootValue,
492	            dockRootCapturedAt: dockRootCapturedAt,
493	            dockRowsCaptureStartedAt: dockRowsCaptureStartedAt,
494	            dockRowsCapturedAt: dockRowsCapturedAt,
495	            dockRows: dockRows,
496	            globalConnectivity: globalConnectivity,
497	            hostSummaries: hostSummaries,
498	            dockSweep: dockSweep,
